use windows::core::{HSTRING, PCWSTR};
use windows::Win32::System::Registry::*;

fn open_subkey(parent: HKEY, path: &str) -> Option<HKEY> {
    let mut key = HKEY::default();
    let wide = HSTRING::from(path);
    let status = unsafe { RegOpenKeyExW(parent, PCWSTR(wide.as_ptr()), None, KEY_READ, &mut key) };
    if status.is_err() { return None; }
    Some(key)
}
fn read_string(key: HKEY, name: &str) -> Option<String> {
    let mut size = 0u32;
    let nw = HSTRING::from(name);
    let _ = unsafe { RegGetValueW(key, None, PCWSTR(nw.as_ptr()), RRF_RT_REG_SZ, None, None, Some(&mut size)) };
    if size == 0 { return None; }
    let mut buf = vec![0u16; (size as usize / 2) + 1];
    let mut cap = (buf.len() * 2) as u32;
    let st = unsafe { RegGetValueW(key, None, PCWSTR(nw.as_ptr()), RRF_RT_REG_SZ, None, Some(buf.as_mut_ptr().cast()), Some(&mut cap)) };
    if st.is_err() { return None; }
    let end = buf.iter().position(|c| *c == 0).unwrap_or(buf.len());
    if end == 0 { return None; }
    String::from_utf16(&buf[..end]).ok()
}

#[test]
fn trace() {
    let ep = open_subkey(HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render\{04b3884f-fbb8-46b9-b5d4-d29e882551a0}").unwrap();
    let fx = open_subkey(ep, "FxProperties").unwrap();
    let name = r"{d04e05a6-594b-4fb6-a80d-01af5eed7d1d},5";
    let (base, _idx) = name.split_once(',').unwrap();
    let known = "d04e05a6-594b-4fb6-a80d-01af5eed7d1d";
    println!("base  = {base:?}");
    println!("trim  = {:?}", base.trim_start_matches('{'));
    println!("eq    = {}", known.eq_ignore_ascii_case(base.trim_start_matches('{')));
    println!("read  = {:?}", read_string(fx, name));
    let v = read_string(fx, name).unwrap_or_default();
    println!("upper = {:?}", v.to_uppercase());
    println!("match = {}", "{EACD2258-FCAC-4FF4-B36D-419E924A6D79}".to_string().contains(&v.to_uppercase()));
}
