//! Output level measurement.
//!
//! Used to prove — rather than assume — that a gain change SonusPilot wrote to
//! \`config.txt\` actually altered the audio leaving the endpoint. The endpoint
//! meter reports the signal *after* the endpoint's FX chain has processed it,
//! so a preamp change made by APO shows up here.

use windows::core::Interface;
use windows::Win32::Media::Audio::eConsole;
use windows::Win32::Media::Audio::Endpoints::IAudioMeterInformation;
use windows::Win32::Media::Audio::{eRender, IMMDevice, IMMDeviceEnumerator, MMDeviceEnumerator};
use windows::Win32::System::Com::{
    CoCreateInstance, CoInitializeEx, CLSCTX_ALL, COINIT_APARTMENTTHREADED,
};

/// A level reading from the default render endpoint.
pub struct Level {
    pub peak: f32,
}

/// Activate the audio meter on the default render endpoint.
fn default_endpoint_meter() -> Option<IAudioMeterInformation> {
    unsafe {
        // A COM apartment may already be initialised on this thread; failing
        // to initialise is not itself an error, and CoCreateInstance is what
        // actually decides whether the interface is available.
        let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);

        let enumerator: IMMDeviceEnumerator = CoCreateInstance(&MMDeviceEnumerator, None, CLSCTX_ALL).ok()?;
        let device: IMMDevice = enumerator.GetDefaultAudioEndpoint(eRender, eConsole).ok()?;
        device.Activate::<IAudioMeterInformation>(CLSCTX_ALL, None).ok()
    }
}

/// Measure the default endpoint.
pub fn measure_default_endpoint() -> Level {
    default_endpoint_meter()
        .and_then(|meter| {
            let mut peak = 0.0;
            unsafe { meter.GetPeakValue(&mut peak).ok()? };
            Some(Level { peak })
        })
        .unwrap_or(Level { peak: 0.0 })
}
EOF
